import json,sys
d=json.load(sys.stdin)
items=d.get('items',d) if isinstance(d,dict) else d
def walk(its):
    for it in its:
        if it.get('status')!='done':
            print(f\"{it['id']:<48} {it.get('status'):<9} owner={it.get('owner','') or '-':<14} {(it.get('detail') or it.get('title') or '')[:80]}\")
        for k in ('children','items'):
            if it.get(k): walk(it[k])
walk(items if isinstance(items,list) else [])
" 2>/dev/null | head -60
